\section{Introduction}

\subsection{Setting}
Let $V$ be a finite set of \emph{sites}, $n = |V|$, and let $\Om = \{0,1\}^V$ be the discrete cube of \emph{configurations}; we write $\eta_v = 1$ for ``$v$ is open'' and $\eta_v = 0$ for ``$v$ is closed''. For $p \in [0,1]$ the $p$-biased product measure assigns to $\eta \in \Om$ the weight
\[
  \mu_p(\eta) \;=\; \prod_{v\in V}\bigl(p\,\one\{\eta_v=1\} + (1-p)\one\{\eta_v=0\}\bigr) \;=\; p^{|\eta|}(1-p)^{\,n-|\eta|},
  \qquad |\eta| := \#\{v:\eta_v=1\},
\]
and to an event $A \subseteq \Om$ the probability $\mu_p(A) = \sum_{\eta\in A}\mu_p(\eta)$. We write $\Ep[f] = \sum_\eta \mu_p(\eta)f(\eta)$ and abbreviate
\[
  q := p(1-p),
\]
the per-site variance. Except where stated we assume $0<p<1$, so $q>0$ and $\mu_p(\eta)>0$ for all $\eta$.

An event $A$ is \emph{increasing} if $\eta\le\xi$ pointwise and $\eta\in A$ imply $\xi\in A$. For $v \in V$ write $\eta^{v\to1},\eta^{v\to0}$ for the configurations obtained by forcing $v$ open resp.\ closed. The site $v$ is \emph{pivotal} for $A$ at $\eta$ if $\eta^{v\to1}\in A$ and $\eta^{v\to0}\notin A$; the set of such $\eta$ is $\Piv_v(A)$ and the \emph{influence} of $v$ is $I_v = \mu_p(\Piv_v(A))$. Russo's formula states that for increasing $A$ the polynomial $P(p) := \mu_p(A)$ satisfies $P'(p) = \sum_v I_v$.

Two inequalities are central to the theory of sharp thresholds. With $P = \mu_p(A)$:
\begin{align}
  P(1-P) &\;\le\; q\sum_{v\in V} I_v, \tag{P}\\
  q\sum_{v\in V} I_v^2 &\;\le\; P(1-P). \tag{L}
\end{align}
Inequality (P), with Russo's formula, is the differential inequality $P(1-P)\le q P'(p)$ whose integration bounds the width of the threshold window. Inequality (L), with Cauchy--Schwarz, gives the square-root law $\bigl(\sum_v I_v\bigr)^2 \le n P(1-P)/q$, hence $\sum_v I_v \le \sqrt n$ at $p=1/2$.

The two inequalities bound the influence vector from opposite sides and are classically proved by unrelated means: (P) by a martingale or hybrid-path argument, (L) by Bessel's inequality for the \emph{incomplete} orthogonal family $\{1\}\cup\{\psi_v\}$. We show that both are shadows of one exact identity, obtained once the orthogonal family is completed.

\subsection{Contributions}
\begin{enumerate}
\item A self-contained construction of the $p$-biased Fourier basis $\{\psi_S\}_{S\subseteq V}$, with full orthogonality (Theorem~\ref{thm:orth}), a reproducing-kernel identity (Theorem~\ref{thm:kernel}), completeness (Theorem~\ref{thm:complete}) and Parseval (Theorem~\ref{thm:parseval}). All proofs are finite algebra.
\item The biased Plancherel identity for Boolean functions (Theorem~\ref{thm:plancherel}).
\item The exact energy decomposition for increasing events (Theorem~\ref{thm:energy}), with the equality case and strict improvement for (L).
\item The site energy identity (Theorem~\ref{thm:site}), the biased analogue of $\mathrm{Inf}_v(f)=\sum_{S\ni v}\hat f(S)^2$.
\item The exact Efron--Stein/Poincar\'e defect for arbitrary real functions (Theorem~\ref{thm:defect}) and its increasing-event form with equality criterion (Theorem~\ref{thm:poincare}).
\item The synthesis: (P) and (L) are one spectrum read against two weights (Section~\ref{sec:synth}).
\end{enumerate}

\section{The biased expectation and the product rule}

\begin{definition}
For an event $A$ the \emph{sign indicator} is $g_A(\eta) = +1$ if $\eta\in A$ and $-1$ otherwise. Then $\Ep[g_A]=2P-1$, $g_A^2\equiv1$ and $\Var_p(g_A) = 1-(2P-1)^2 = 4P(1-P)$.
\end{definition}

\begin{theorem}[Product rule]\label{thm:prod}
For every family $(g_v)_{v\in V}$ of functions $\{0,1\}\to\mathbb R$,
\[
  \Ep\Bigl[\eta\mapsto\prod_{v\in V}g_v(\eta_v)\Bigr] \;=\; \prod_{v\in V}\bigl(p\,g_v(1) + (1-p)\,g_v(0)\bigr).
\]
\end{theorem}

\begin{proof}
Expanding the right-hand product by distributivity gives a sum over all choices $\eta : V\to\{0,1\}$ of one summand from each factor,
\[
  \prod_{v}\sum_{b\in\{0,1\}}\bigl(b\,?\,p:(1-p)\bigr)g_v(b)
  \;=\; \sum_{\eta\in\Om}\prod_{v}\bigl(\eta_v\,?\,p:(1-p)\bigr)g_v(\eta_v).
\]
Factoring each term into $\mu_p(\eta)\prod_v g_v(\eta_v)$ gives the left-hand side.
\end{proof}

Two consequences used throughout: $\Ep[c]=c$ for constants, and linearity of $\Ep$ over finite sums.

\section{Characters and orthogonality}

\begin{definition}
For $v\in V$ set $\psi_v(\eta) = 1-p$ if $\eta_v=1$ and $\psi_v(\eta) = -p$ if $\eta_v=0$; for $S\subseteq V$ put $\psi_S = \prod_{v\in S}\psi_v$, with $\psi_\emptyset\equiv1$.
\end{definition}

By Theorem~\ref{thm:prod}, $\Ep[\psi_v] = p(1-p)+(1-p)(-p)=0$ and $\Ep[\psi_v^2] = p(1-p)^2+(1-p)p^2 = q$.

\begin{theorem}[Full orthogonality]\label{thm:orth}
For all $S,T\subseteq V$,
\[
  \Ep[\psi_S\psi_T] = \begin{cases} q^{|S|}, & S=T,\\ 0,& S\neq T.\end{cases}
\]
\end{theorem}

\begin{proof}
Write $\psi_S(\eta) = \prod_{v\in V}h^S_v(\eta_v)$ with $h^S_v=\psi$ for $v\in S$ and $h^S_v\equiv1$ otherwise, so $\psi_S\psi_T$ is a product of one-coordinate functions. Theorem~\ref{thm:prod} gives a product whose $v$-th factor equals $1$ if $v\notin S\cup T$, equals $p(1-p)+(1-p)(-p)=0$ if $v \in S\triangle T$, and equals $p(1-p)^2+(1-p)p^2 = q$ if $v\in S\cap T$. If $S\ne T$ some factor vanishes; if $S=T$ the product is $q^{|S|}$.
\end{proof}

\begin{definition}
For $f:\Om\to\mathbb R$ and $S\subseteq V$ define the \emph{Fourier coefficient} and \emph{level energy}
\[
  \hat f(S) = \frac{\Ep[f\,\psi_S]}{q^{|S|}},\qquad w_S(f) = q^{|S|}\hat f(S)^2 \ge 0 .
\]
Thus $\hat f(\emptyset) = \Ep[f]$ and $\Ep[f\psi_S] = \hat f(S)q^{|S|}$. We write $\deg f = \max\{|S|:\hat f(S)\neq0\}$.
\end{definition}

\section{Reproducing kernel, completeness and Parseval}

\begin{theorem}[Reproducing-kernel identity]\label{thm:kernel}
For $0<p<1$ and all $\xi,\eta\in\Om$,
\[
  K_p(\xi,\eta) \;:=\; \sum_{S\subseteq V}\ \prod_{v\in S}\frac{\psi_v(\xi)\psi_v(\eta)}{q}
  \;=\; \begin{cases}\mu_p(\eta)^{-1}, & \xi=\eta,\\ 0,&\xi\neq\eta.\end{cases}
\]
\end{theorem}

\begin{proof}
Summing $\prod_{v\in S}a_v$ over all $S\subseteq V$ expands $\prod_{v\in V}(1+a_v)$, so $K_p(\xi,\eta) = \prod_v\bigl(1+\psi_v(\xi)\psi_v(\eta)/q\bigr)$. Case analysis on the $v$-th factor:
\[
  1+\frac{\psi_v(\xi)\psi_v(\eta)}{q} = \begin{cases}
  1+\dfrac{(1-p)^2}{p(1-p)} = \dfrac1p, & \xi_v=\eta_v=1,\\[6pt]
  1+\dfrac{p^2}{p(1-p)} = \dfrac1{1-p}, & \xi_v=\eta_v=0,\\[6pt]
  1+\dfrac{(1-p)(-p)}{p(1-p)} = 0, & \xi_v\neq\eta_v.
  \end{cases}
\]
If $\xi\neq\eta$ a factor vanishes; otherwise the product is $\prod_v\bigl(\eta_v\,?\,p^{-1}:(1-p)^{-1}\bigr) = \mu_p(\eta)^{-1}$.
\end{proof}

\begin{theorem}[Completeness]\label{thm:complete}
For $0<p<1$, every $f:\Om\to\mathbb R$ satisfies $f(\eta) = \sum_{S\subseteq V}\hat f(S)\psi_S(\eta)$ for all $\eta$.
\end{theorem}

\begin{proof}
Fix $\eta$. Unfolding the definition,
\[
  \hat f(S)\psi_S(\eta) = \frac1{q^{|S|}}\sum_\xi \mu_p(\xi)f(\xi)\psi_S(\xi)\psi_S(\eta)
  = \sum_\xi \mu_p(\xi)f(\xi)\prod_{v\in S}\frac{\psi_v(\xi)\psi_v(\eta)}{q}.
\]
Summing over $S$ and exchanging the two finite sums gives $\sum_\xi \mu_p(\xi)f(\xi)K_p(\xi,\eta)$, which by Theorem~\ref{thm:kernel} equals $\mu_p(\eta)f(\eta)\mu_p(\eta)^{-1} = f(\eta)$.
\end{proof}

\begin{theorem}[Parseval]\label{thm:parseval}
For $0<p<1$ and all $f,g:\Om\to\mathbb R$,
$\Ep[fg] = \sum_{S\subseteq V}q^{|S|}\hat f(S)\hat g(S)$.
\end{theorem}

\begin{proof}
Substitute the expansion of Theorem~\ref{thm:complete} for $f$ and use linearity: $\Ep[fg] = \sum_S \hat f(S)\Ep[\psi_S g] = \sum_S \hat f(S)\hat g(S)q^{|S|}$.
\end{proof}

\begin{corollary}[Variance form]\label{cor:var}
$\Var_p(f) = \Ep[f^2]-(\Ep[f])^2 = \sum_{S\neq\emptyset}w_S(f)$.
\end{corollary}

\begin{proof}
Take $g=f$ in Theorem~\ref{thm:parseval} and split off $S=\emptyset$, whose term is $(\Ep f)^2$.
\end{proof}

\section{Increasing events: the energy decomposition}

Throughout, $A$ is increasing, $g=g_A$, $P=\mu_p(A)$, $I_v = \mu_p(\Piv_v(A))$.

\begin{lemma}[Low-level coefficients]\label{lem:low}
For $0<p<1$: $\hat g(\emptyset) = 2P-1$ and $\hat g(\{v\}) = 2I_v$.
\end{lemma}

\begin{proof}
The first is $\Ep[g]$. For the second, condition on the coordinate $v$: writing configurations as (value at $v$, rest $\zeta$) with product weight $\mu_p^{(v)}$,
\[
  \Ep[g\,\psi_v] = \sum_\zeta \mu_p^{(v)}(\zeta)\,p(1-p)\bigl(g(\zeta^{v\to1})-g(\zeta^{v\to0})\bigr).
\]
Since $A$ is increasing, the bracket equals $2$ when $v$ is pivotal and $0$ otherwise; so $\Ep[g\psi_v]=2qI_v$ and $\hat g(\{v\}) = 2I_v$.
\end{proof}

\begin{theorem}[Biased Plancherel for Boolean functions]\label{thm:plancherel}
For $0<p<1$ and any event $A$, $\sum_{S\subseteq V}w_S(g_A) = 1$.
\end{theorem}

\begin{proof}
$g_A^2\equiv1$, so $\Ep[g_Ag_A]=1$; apply Theorem~\ref{thm:parseval}.
\end{proof}

\begin{definition}
The \emph{high energy} of $A$ is $R(A) = \sum_{|S|\ge2}w_S(g_A)\ge0$.
\end{definition}

\begin{theorem}[Exact energy decomposition]\label{thm:energy}
For $0<p<1$ and increasing $A$,
\[
  4P(1-P) \;=\; 4q\sum_{v\in V}I_v^2 \;+\; R(A).
\]
\end{theorem}

\begin{proof}
Split the total mass of Theorem~\ref{thm:plancherel} by level: $1 = w_\emptyset + \sum_v w_{\{v\}} + R(A)$. By Lemma~\ref{lem:low}, $w_\emptyset = (2P-1)^2$ and $w_{\{v\}} = q(2I_v)^2 = 4qI_v^2$. Rearrange using $1-(2P-1)^2 = 4P(1-P)$.
\end{proof}

\begin{corollary}[$\ell^2$ influence bound; equality case]\label{cor:l2}
For $0<p<1$ and increasing $A$, $q\sum_v I_v^2 \le P(1-P)$, with equality iff $\hat g_A(S)=0$ for every $S$ with $|S|\ge2$.
\end{corollary}

\begin{corollary}[Strict improvement]
If $\hat g_A(S)\neq0$ for some $|S|\ge2$ then $q\sum_v I_v^2 < P(1-P)$, the gap being at least $q^{|S|}\hat g_A(S)^2/4$.
\end{corollary}

\begin{corollary}[Square-root law]
$\bigl(\sum_v I_v\bigr)^2 \le n\sum_v I_v^2 \le nP(1-P)/q$; in particular $\sum_v I_v \le \sqrt n$ at $p=1/2$.
\end{corollary}

\begin{example}[Grid crossing]
Let $A_n$ be the left-to-right open crossing of the $n\times n$ grid at $p=1/2$, an increasing event on $n^2$ sites. Since $4q=1$ there, Theorem~\ref{thm:energy} reads $4P(1-P) = \sum_v I_v^2 + R(A_n)$: the absence of a dominant site is precisely the statement that $R(A_n)$ carries most of the mass.
\end{example}

\section{One-coordinate calculus and the exact Efron--Stein defect}

\begin{definition}
Say $f$ is \emph{independent of $v$} (written $f\perp v$) if $f(\eta^{v\to b}) = f(\eta)$ for all $\eta,b$. Define
\[
  (D_vf)(\eta) = f(\eta^{v\to1})-f(\eta^{v\to0}),\qquad
  (A_vf)(\eta) = p f(\eta^{v\to1}) + (1-p)f(\eta^{v\to0}).
\]
Both $D_vf$ and $A_vf$ are independent of $v$, as is $\psi_S$ for $v\notin S$; and the class of functions independent of $v$ is closed under products.
\end{definition}

\begin{lemma}[One-coordinate decomposition]\label{lem:decomp}
$f = A_vf + \psi_v\,D_vf$ pointwise, for every $f$ and every $v$.
\end{lemma}

\begin{proof}
If $\eta_v=1$ then $\eta^{v\to1}=\eta$ and $\psi_v(\eta)=1-p$, so the right side is $pf(\eta)+(1-p)f(\eta^{v\to0})+(1-p)(f(\eta)-f(\eta^{v\to0})) = f(\eta)$. The case $\eta_v=0$ is symmetric with $\psi_v(\eta)=-p$.
\end{proof}

\begin{lemma}[Two one-coordinate integrals]\label{lem:int}
If $h\perp v$ then $\Ep[\psi_v h]=0$ and $\Ep[\psi_v^2 h] = q\,\Ep[h]$.
\end{lemma}

\begin{proof}
Conditioning on the coordinate $v$, $\Ep[F] = \sum_\zeta \mu_p^{(v)}(\zeta)\bigl(pF(\zeta^{v\to1})+(1-p)F(\zeta^{v\to0})\bigr)$. With $F=\psi_vh$ the bracket is $\bigl(p(1-p)+(1-p)(-p)\bigr)h(\zeta)=0$; with $F=\psi_v^2h$ it is $\bigl(p(1-p)^2+(1-p)p^2\bigr)h(\zeta) = q h(\zeta)$.
\end{proof}

\begin{lemma}\label{lem:erase}
For $0<p<1$ and $v\in S$, $\hat f(S) = \widehat{D_vf}(S\setminus\{v\})$. Moreover if $f\perp v$ then $\hat f(S)=0$ for every $S\ni v$.
\end{lemma}

\begin{proof}
Write $\psi_S = \psi_v\psi_{S\setminus v}$ and insert Lemma~\ref{lem:decomp}:
$f\psi_S = \psi_v(A_vf\cdot\psi_{S\setminus v}) + \psi_v^2(D_vf\cdot\psi_{S\setminus v})$, both bracketed factors being independent of $v$. Lemma~\ref{lem:int} gives $\Ep[f\psi_S] = q\,\Ep[D_vf\cdot\psi_{S\setminus v}]$; divide by $q^{|S|} = q\cdot q^{|S\setminus v|}$. The second claim is the first identity of Lemma~\ref{lem:int} applied to $h = f\psi_{S\setminus v}$.
\end{proof}

\begin{theorem}[Site energy identity]\label{thm:site}
For $0<p<1$ and every $f$, $\displaystyle\sum_{S\ni v}w_S(f) = q\,\Ep\bigl[(D_vf)^2\bigr]$.
\end{theorem}

\begin{proof}
Reindex by $T = S\setminus\{v\}$, a bijection from $\{S : v\in S\}$ onto $\{T : v\notin T\}$ with $|S|=|T|+1$. Lemma~\ref{lem:erase} gives
$\sum_{S\ni v}q^{|S|}\hat f(S)^2 = q\sum_{T\not\ni v}w_T(D_vf)$. Since $D_vf\perp v$, its coefficients vanish on sets containing $v$, so the restricted sum equals the full sum, which by Theorem~\ref{thm:parseval} is $\Ep[(D_vf)^2]$.
\end{proof}

\begin{theorem}[Exact Efron--Stein/Poincar\'e defect]\label{thm:defect}
For $0<p<1$ and every $f:\Om\to\mathbb R$,
\[
  q\sum_{v\in V}\Ep\bigl[(D_vf)^2\bigr] \;-\; \Var_p(f) \;=\; \sum_{S\neq\emptyset}\bigl(|S|-1\bigr)w_S(f)\;\ge\;0 .
\]
In particular $\Var_p(f) \le q\sum_v \Ep[(D_vf)^2]$.
\end{theorem}

\begin{proof}
Sum Theorem~\ref{thm:site} over $v$: each level $S$ is counted once for each of its $|S|$ elements, so the left summand is $\sum_S|S|w_S(f) = \sum_{S\neq\emptyset}|S|w_S(f)$. Subtract $\Var_p(f)=\sum_{S\neq\emptyset}w_S(f)$ (Corollary~\ref{cor:var}) termwise. Nonnegativity holds since $|S|\ge1$ on nonempty $S$.
\end{proof}

\section{Specialisation to increasing events}

\begin{lemma}\label{lem:deriv01}
If $A$ is increasing then $(D_vg_A)(\eta)\in\{0,2\}$ for all $v,\eta$; hence $(D_vg_A)^2 = 2D_vg_A$, and $D_vg_A = 2\cdot\one_{\Piv_v(A)}$.
\end{lemma}

\begin{proof}
$\eta^{v\to0}\le\eta^{v\to1}$, so monotonicity forbids the pattern $(g(\eta^{v\to1}),g(\eta^{v\to0})) = (-1,+1)$; the three remaining patterns give differences $0,2,0$, and the value $2$ occurs exactly on $\Piv_v(A)$.
\end{proof}

\begin{corollary}\label{cor:der}
For $0<p<1$ and increasing $A$, $\Ep[D_vg_A] = 2I_v$ and $\Ep[(D_vg_A)^2]=4I_v$.
\end{corollary}

\begin{theorem}[Site energy equals influence]\label{thm:siteinf}
For $0<p<1$ and increasing $A$, $\sum_{S\ni v}w_S(g_A) = 4q\,I_v$. Summing over $v$,
\[
  4q\sum_{v\in V} I_v \;=\; \sum_{S\subseteq V}|S|\,w_S(g_A).
\]
\end{theorem}

\begin{theorem}[Poincar\'e defect and its equality case]\label{thm:poincare}
For $0<p<1$ and increasing $A$,
\[
  4q\sum_{v\in V}I_v - 4P(1-P) \;=\; \sum_{S\neq\emptyset}\bigl(|S|-1\bigr)w_S(g_A)\;\ge\;0,
\]
hence $P(1-P)\le q\sum_v I_v$, with equality if and only if $\hat g_A(S)=0$ for every $S$ with $|S|\ge2$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:defect} to $f=g_A$; the left-hand sum becomes $4q\sum_vI_v$ by Corollary~\ref{cor:der}, and $\Var_p(g_A)=4P(1-P)$. The defect is a sum of nonnegative terms; the factor $|S|-1$ vanishes on singletons and is at least $1$ for $|S|\ge2$, so the defect vanishes iff $w_S(g_A)=0$ for all $|S|\ge2$, iff the corresponding coefficients vanish (using $q>0$).
\end{proof}

\section{Synthesis: one spectrum, two weights}\label{sec:synth}

Fix an increasing event $A$ and consider the nonnegative energy spectrum $(w_S)_{S\subseteq V}$ of $g_A$, of total mass $1$ by Theorem~\ref{thm:plancherel}. Both classical inequalities assert that a weighted sum of this spectrum is nonnegative:

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Inequality & Exact identity & Weight $\omega(S)$ \\
\midrule
$q\sum_v I_v^2 \le P(1-P)$ & $4P(1-P)-4q\sum_vI_v^2 = \sum_S\omega(S)w_S$ & $\one\{|S|\ge2\}$ \\
$P(1-P)\le q\sum_v I_v$    & $4q\sum_vI_v-4P(1-P) = \sum_S\omega(S)w_S$   & $|S|-1$ \\
\bottomrule
\end{tabular}
\end{center}

Three consequences.

\emph{(i) Opposite directions, same source.} The inequalities squeeze $P(1-P)$ from either side yet are read off the same spectrum; only the weight differs.

\emph{(ii) Identical equality cases.} Both weights vanish exactly on levels $0$ and $1$ and are positive above, so both inequalities are tight precisely for events of Fourier degree at most one. Among monotone events these are constants and dictators $A=\{\eta:\eta_{v_0}=1\}$, for which $P=p$, $I_{v_0}=1$ and $I_v=0$ otherwise, both inequalities reducing to $p(1-p)=q$.

\emph{(iii) Chaining.} Subtracting the first identity from the second eliminates $P(1-P)$ and gives, for every increasing event, the strikingly simple
\[
  4q\Bigl(\sum_{v\in V} I_v - \sum_{v\in V} I_v^2\Bigr) \;=\; \sum_{|S|\ge2}|S|\,w_S(g_A),
\]
an exact expression for the spread between the $\ell^1$ and $\ell^2$ norms of the influence vector as the high-level energy weighted by level. In particular $\sum_v I_v = \sum_v I_v^2$, i.e.\ every influence is $0$ or $1$, exactly for events of degree at most one.

\section{Algorithms}

All quantities are exactly computable on a finite site set.

\emph{Algorithm A (direct transform).} Compute $\hat f(S) = q^{-|S|}\sum_\eta\mu_p(\eta)f(\eta)\psi_S(\eta)$ for all $S$: $O(4^n n)$ operations.

\emph{Algorithm B (biased fast Walsh transform).} Because $\psi_S$ factorises coordinatewise, so does the transform. Iterate over coordinates $v=1,\dots,n$, applying in place, to every pair of table entries differing only in coordinate $v$ (with $a$ the entry having $v$ open),
\[
  \begin{pmatrix}a\\ b\end{pmatrix}\longmapsto\begin{pmatrix}p\,a+(1-p)\,b\\ a-b\end{pmatrix}.
\]
This is exactly the decomposition $f = A_vf + \psi_v D_vf$ of Lemma~\ref{lem:decomp} performed one coordinate at a time; after $n$ passes the entry indexed by $S$ is $\hat f(S)$. Cost $O(n2^n)$, exact in rational arithmetic.

\emph{Algorithm C (influences and defects).} Sum $\mu_p$ over $\Piv_v(A)$ for each $v$ to get the influences, run Algorithm B on $g_A$, and evaluate both defects from the spectrum, verifying Theorems~\ref{thm:energy} and \ref{thm:poincare} as exact rational identities. Cost $O(n2^n)$.

\section{Discussion}

\emph{Why completeness matters.} The degree-$\le1$ theory --- orthogonality of $\{1\}\cup\{\psi_v\}$ and Bessel's inequality --- already yields the $\ell^2$ influence bound and hence the square-root law, but cannot say when the bound is tight or by how much it fails: Bessel is an inequality precisely because the family is incomplete. Supplying the remaining characters upgrades it to an identity with explicit remainder; the sole additional idea is the kernel computation of Theorem~\ref{thm:kernel}.

\emph{Robustness.} Theorem~\ref{thm:defect} needs no monotonicity. Monotonicity enters only via Lemma~\ref{lem:deriv01}, which converts a second moment into a first moment, and this is why the monotone Poincar\'e inequality involves $\sum_v I_v$.

\emph{Endpoints and normalisation.} At $p\in\{0,1\}$ we have $q=0$, the characters degenerate and both inequalities read $0\le0$; completeness statements therefore require $0<p<1$. Theorems~\ref{thm:prod} and \ref{thm:orth} are polynomial identities in $p$ and hold for all real $p$. One may instead use the orthonormal characters $\chi_S = q^{-|S|/2}\psi_S$, whence $w_S(f) = \Ep[f\chi_S]^2$; we keep the unnormalised $\psi_S$ so that all quantities remain polynomials in $p$, which is essential for exact rational verification. At $p=1/2$ the energies $w_S$ coincide with the classical unbiased Fourier weights.

\emph{Sharp thresholds.} With Russo's formula, Theorem~\ref{thm:poincare} becomes the exact differential identity
\[
  4q\,P'(p) \;=\; 4P(1-P) + \sum_{S\neq\emptyset}(|S|-1)w_S(g_A),
\]
so any lower bound on high-level energy translates directly into a quantitatively narrower threshold window.

\section{Future work}

\emph{Hypercontractivity.} The next natural weight is exponential: for $\rho\in[0,1]$ the biased noise operator acts by $\widehat{T_\rho f}(S)=\rho^{|S|}\hat f(S)$, and $\|T_\rho f\|_4\le\|f\|_2$ for $\rho^2\le q/\max(p,1-p)^2$ is the missing ingredient between the present development and the Kahn--Kalai--Linial theorem and Talagrand's refinements. Hypercontractivity tensorises, and tensorisation is precisely repeated application of the product rule (Theorem~\ref{thm:prod}); the only new input is a two-variable polynomial inequality in one coordinate.

\emph{General level weights.} Study the family $\sum_S\omega(|S|)w_S\ge0$ for nonnegative $\omega$ vanishing on $\{0,1\}$; the $\ell^2$ bound and Poincar\'e are its two simplest members. Which $\omega$ give useful threshold information, and what are the extremal events?

\emph{Site-dependent densities.} Sections 2--4 go through verbatim for product measures with densities $p_v$, replacing $q^{|S|}$ by $\prod_{v\in S}p_v(1-p_v)$; with $\partial P/\partial p_v = I_v$, the analogues of Theorems~\ref{thm:defect} and \ref{thm:poincare} should follow with the same proofs.

